"""🏇 Round 4 horse: the body of every scale restated by hand after the review (wider forehand and neck base, deeper and wider head, trunk pieces that share their seam section, shoulder and thigh masses that stand proud of the trunk wall, a 1:500 body without grooves). Stations are places on a 1.61 m warmblood in the rest pose of the rig (x ahead from the hip joint, y up, z lateral); see r3-animals-horse.md, section "Round 4 review".

Loaded by r3-horse-model.py through importlib; `body(n)` returns the body list of scale 1:n.
"""
import importlib.util
import os

HERE = os.path.dirname(os.path.abspath(__file__))
spec = importlib.util.spec_from_file_location("kit", os.path.join(HERE, "r3-horse-kit.py"))
K = importlib.util.module_from_spec(spec)
spec.loader.exec_module(K)
loft, along, ellipsoid, SIDES, world = K.loft, K.along, K.ellipsoid, K.SIDES, K.world

COAT, HAIR, SKIN, EYE, HORN = "short-coat", "mane-tail-hair", "bare-skin", "eye-surface", "hoof-horn"
T_COAT, T_HAIR, T_HORN, T_SKIN, T_EYE = 0.62, 0.2, 0.3, 0.22, 0.04
HEAD_A = K.F["head"][2]


def tu(x, top, under, rz, e=None):
    """🫁 A vertical trunk section from its top line, its under line and its half width."""
    return (x, (top + under) / 2, 0.0, (top - under) / 2, rz, 0.0, e)


def tuck(x, top, under, rz, k=0.86):
    """🪡 The hidden end of a trunk piece: the section at x shrunk about its centre so that it lies inside the neighbour."""
    return (x, (top + under) / 2, 0.0, (top - under) / 2 * k, rz * k, 0.0, None)


def flat(y, xc, rx, rz, z=0.0, e=None):
    """🥞 A horizontal section (hoof, thigh): centre, half length, half width."""
    return (xc, y, z, rx, rz, -90.0, e)


def shrink(st, k=0.86):
    """🧶 A neck section shrunk about its centre: the hidden end of a neck piece."""
    return (st[0], st[1], st[2], st[3] * k, st[4] * k, st[5])


