def trunk(n):
    """🐴 Croup, loin and barrel: three lofts on pelvis, lumbar and thorax that carry the same section at their two seams (x = 0.2 and x = 0.5) and end hidden inside the neighbour."""
    p, l, c = TRUNK[n]
    return [
        loft("pelvis", "pelvis", [tu(*s) for s in p] + [tuck(0.29, 1.548, 1.026, 0.266)], exp=2.4),
        loft("hindbody", "lumbar", [tuck(0.11, 1.598, 1.048, 0.276)] + [tu(*s) for s in l] + [tuck(0.59, 1.502, 0.915, 0.285)], exp=2.4),
        loft("chest", "thorax", [tuck(0.41, 1.525, 0.983, 0.268)] + [tu(*s) for s in c], exp=2.4 if n >= 100 else 2.4),
    ]


