def neck(n):
    """🦒 The neck: pieces on neck-1, neck-2 and neck-3 that share the section at their seams (stations 5 and 8 of the 1:50 list) and end hidden; 0.34 m wide where it leaves the shoulders, 0.12 m at the throat."""
    s = NECK50
    if n == 500:
        return [
            loft("neck-a", "neck-1", [s[0], s[1], s[3], s[5], shrink(s[6])], exp=2.2),
            loft("neck-b", "neck-2", [shrink(s[4]), s[5], s[8], s[10], s[11]], exp=2.2),
        ]
    a = {50: [s[0], s[1], s[2], s[3], s[4], s[5]], 100: [s[0], s[1], s[2], s[4], s[5]], 200: [s[0], s[1], s[3], s[5]]}[n]
    b = {50: [s[5], s[6], s[7], s[8]], 100: [s[5], s[6], s[8]], 200: [s[5], s[8]]}[n]
    c = {50: [s[8], s[9], s[10], s[11]], 100: [s[8], s[9], s[10], s[11]], 200: [s[8], s[10], s[11]]}[n]
    return [
        loft("neck-1", "neck-1", a + [shrink(s[6])], exp=2.2),
        loft("neck-2", "neck-2", [shrink(s[4])] + b + [shrink(s[9])], exp=2.2),
        loft("neck-3", "neck-3", [shrink(s[7])] + c, exp=2.2),
    ]


