def body(n):
    """🧩 The body list of scale 1:n."""
    b = trunk(n)
    if n == 50:
        b.append(loft("withers", "thorax", [tu(0.74, 1.505, 1.42, 0.06), tu(0.88, 1.535, 1.42, 0.07), tu(1.0, 1.585, 1.42, 0.074), tu(1.1, 1.612, 1.43, 0.07), tu(1.19, 1.604, 1.44, 0.068), tu(1.29, 1.575, 1.43, 0.075)], exp=2.0))
        for name, sfx, m in SIDES:
            b.append(ellipsoid(f"{name}-hip-point", "pelvis", (0.2, 1.462, 0.222), (0.095, 0.07, 0.034), angle=-35.0, mirror=m))
            b.append(ellipsoid(f"{name}-breast", "thorax", (1.35, 1.09, 0.085), (0.075, 0.105, 0.088), mirror=m))
    b += neck(n) + head(n) + hair(n)
    b += {50: legs50, 100: legs100, 200: legs200, 500: legs500}[n]()
    return b
